  data-radius={radius}
  data-color={color}
  data-border-color={borderColor}
  data-opacity={opacity}
  data-spread={spread}
  data-mode={mode}
  data-smoothing={smoothing}
  data-disabled={disabled ? 'true' : 'false'}
  {...props}
>
