      sheenEl.style.inset = '0';
      sheenEl.style.pointerEvents = 'none';
      sheenEl.style.transition = 'opacity 300ms';
      sheenEl.style.opacity = 'calc(var(--exhuma-spotlight-opacity, 0) * 0.25)';
