import { View, StyleSheet, type ViewProps } from 'react-native';

export type DiamondGridMode = 'rhombic' | 'isometric';

export interface DiamondGridProps extends ViewProps {
  gap?: number;
  mode?: DiamondGridMode;
  responsive?: boolean;
}

