  gap = 16,
  mode = 'rhombic' as DiamondGridMode,
  responsive = false,
  style,
  children,
  ...props
}) => {
  const childrenArray = useMemo(() => React.Children.toArray(children), [children]);

  const columnGroups = useMemo(() => {
    const cols: React.ReactNode[][] = Array.from({ length: 7 }, () => []);
