          setTimeout(() => portal.remove(), duration);
        };

        backdrop.addEventListener('click', dismiss);
        closeBtn.addEventListener('click', dismiss);
      });
    });
  }

  document.addEventListener('DOMContentLoaded', initExpandable);
  initExpandable();
</script>

